import React from "react";
import { FaSearch, FaFilter } from "react-icons/fa";
import TechnicianItem from "./TechnicianItemComponent";
import FilterSheet from "./FilterSheetComponent";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class TechniciansPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      technicians: [],
      searchTerm: "",
      isFilterOpen: false,

      filterProvince: "",
      filterCity: "",
      filterSpecialty: "",

      loading: true,
      authenticated: false,
      error: "",
    };

    this.handleSearchChange = this.handleSearchChange.bind(this);
    this.openFilter = this.openFilter.bind(this);
    this.closeFilter = this.closeFilter.bind(this);
    this.applyFilter = this.applyFilter.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getTechnicians();
      }
    );
  }

  // =====================================================
  // دریافت تعمیرکاران
  // GET /users
  // =====================================================

  getTechnicians = () => {
    const token = localStorage.getItem("token");

    this.setState({
      loading: true,
      error: "",
    });

    fetch(`${API_URL}/users`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then(async (response) => {
        const data = await response.json();

        console.log("========== USERS RESPONSE ==========");
        console.log(data);
        console.log("====================================");

        if (!response.ok) {
          throw new Error(
            data?.message || "خطا در دریافت تعمیرکاران"
          );
        }

        return data;
      })
      .then((data) => {
        if (data.status === "0") {
          throw new Error(
            data.message || "دریافت تعمیرکاران با خطا مواجه شد."
          );
        }

        /*
         * API ممکن است آرایه را مستقیماً داخل users
         * یا داخل data.users برگرداند.
         */

        let users = [];

        if (Array.isArray(data.users)) {
          users = data.users;
        } else if (Array.isArray(data.data)) {
          users = data.data;
        } else if (Array.isArray(data.users?.data)) {
          users = data.users.data;
        }

        this.setState({
          technicians: users,
          loading: false,
          error: "",
        });
      })
      .catch((error) => {
        console.error("GET USERS ERROR:", error);

        this.setState({
          technicians: [],
          loading: false,
          error: error.message || "خطا در ارتباط با سرور",
        });
      });
  };

  // =====================================================
  // حذف تعمیرکار
  // POST /delete
  // Body: { id }
  // =====================================================

  handleDelete = (id) => {
    const token = localStorage.getItem("token");

    if (!window.confirm("آیا از حذف این تعمیرکار مطمئن هستید؟")) {
      return;
    }

    fetch(`${API_URL}/delete`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        id: id,
      }),
    })
      .then(async (response) => {
        const data = await response.json();

        console.log("========== DELETE USER ==========");
        console.log(data);
        console.log("=================================");

        if (!response.ok) {
          throw new Error(
            data?.message || "خطا در حذف تعمیرکار"
          );
        }

        return data;
      })
      .then((data) => {
        if (data.status === "0") {
          throw new Error(
            data.message || "حذف تعمیرکار انجام نشد."
          );
        }

        // حذف از لیست بدون درخواست مجدد
        this.setState((prev) => ({
          technicians: prev.technicians.filter(
            (technician) => technician.id !== id
          ),
        }));
      })
      .catch((error) => {
        console.error("DELETE USER ERROR:", error);
        alert(error.message || "خطا در حذف تعمیرکار");
      });
  };

  // =====================================================
  // تغییر وضعیت تعمیرکار
  // POST /active
  // Body: { id }
  // =====================================================

  handleToggleStatus = (id) => {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/active`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        id: id,
      }),
    })
      .then(async (response) => {
        const data = await response.json();

        console.log("========== ACTIVE USER ==========");
        console.log(data);
        console.log("=================================");

        if (!response.ok) {
          throw new Error(
            data?.message || "خطا در تغییر وضعیت تعمیرکار"
          );
        }

        return data;
      })
      .then((data) => {
        if (data.status === "0") {
          throw new Error(
            data.message || "تغییر وضعیت انجام نشد."
          );
        }

        /*
         * چون API فقط id می‌گیرد، بعد از موفقیت
         * وضعیت را در Front تغییر می‌دهیم.
         */

        this.setState((prev) => ({
          technicians: prev.technicians.map((technician) => {
            if (technician.id !== id) {
              return technician;
            }

            return {
              ...technician,
              active:
                Number(technician.active) === 1
                  ? 0
                  : 1,
            };
          }),
        }));
      })
      .catch((error) => {
        console.error("ACTIVE USER ERROR:", error);
        alert(error.message || "خطا در تغییر وضعیت تعمیرکار");
      });
  };

  // =====================================================
  // جستجو
  // =====================================================

  handleSearchChange(e) {
    this.setState({
      searchTerm: e.target.value,
    });
  }

  // =====================================================
  // فیلتر
  // =====================================================

  openFilter() {
    this.setState({
      isFilterOpen: true,
    });
  }

  closeFilter() {
    this.setState({
      isFilterOpen: false,
    });
  }

  applyFilter() {
    this.closeFilter();
  }

  // =====================================================
  // عکس تعمیرکار
  // =====================================================

  getTechnicianImage = (technician) => {
    const image =
      technician.image ||
      technician.img ||
      technician.avatar ||
      technician.profile_image ||
      technician.profpic ||
      technician.picture;

    if (!image) {
      const name = `${technician.name || ""} ${
        technician.family || ""
      }`.trim();

      return `https://ui-avatars.com/api/?name=${encodeURIComponent(
        name || "User"
      )}&background=e9ecef&color=495057&size=80&rounded=true`;
    }

    if (
      String(image).startsWith("http://") ||
      String(image).startsWith("https://")
    ) {
      return image;
    }

    return `https://iranaserviceapp.ir/test/${String(image).replace(
      /^\/+/,
      ""
    )}`;
  };

  // =====================================================
  // نام تعمیرکار
  // =====================================================

  getTechnicianName = (technician) => {
    const fullName = `${technician.name || ""} ${
      technician.family || ""
    }`.trim();

    return fullName || "بدون نام";
  };

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      technicians,
      searchTerm,
      isFilterOpen,
      filterProvince,
      filterCity,
      filterSpecialty,
      loading,
      error,
    } = this.state;

    const search = searchTerm.trim();

    const filteredTechnicians = technicians.filter((technician) =>
      this.getTechnicianName(technician).includes(search)
    );

    return (
      <div>
        <div className="container px-3 pt-3 pb-5">

          {/* جستجو */}
          <div className="d-flex align-items-center gap-2 border rounded-pill px-3 py-2 mb-3 bg-white">
            <input
              type="text"
              placeholder="جستجو..."
              value={searchTerm}
              onChange={this.handleSearchChange}
              className="form-control border-0 shadow-none text-end p-0"
            />

            <FaSearch
              className="text-secondary"
              size={16}
            />
          </div>

          {/* دکمه فیلتر */}
          <div className="d-flex justify-content-end mb-3">
            <button
              type="button"
              onClick={this.openFilter}
              className="btn btn-light border rounded-pill d-flex align-items-center gap-2 px-3 py-2"
              style={{
                transition: "background-color 0.15s ease",
              }}
            >
              <span>فیلتر</span>

              <FaFilter
                className="text-secondary"
                size={14}
              />
            </button>
          </div>

          {/* عنوان */}
          <div className="bg-light text-center rounded-3 py-3 mb-1">
            <span className="text-primary fw-semibold">
              تعمیرکاران
            </span>
          </div>

          {/* Loading */}
          {loading && (
            <div className="text-center text-muted py-5">
              در حال دریافت تعمیرکاران...
            </div>
          )}

          {/* Error */}
          {!loading && error && (
            <div className="text-center text-danger py-5">
              {error}

              <div className="mt-3">
                <button
                  type="button"
                  className="btn btn-outline-primary btn-sm"
                  onClick={this.getTechnicians}
                >
                  تلاش مجدد
                </button>
              </div>
            </div>
          )}

          {/* لیست */}
          {!loading &&
            !error &&
            filteredTechnicians.map((technician) => (
              <TechnicianItem
                key={technician.id}
                technician={{
                  ...technician,
                  displayName:
                    this.getTechnicianName(technician),
                  avatar:
                    this.getTechnicianImage(technician),
                }}
                onDelete={this.handleDelete}
                onToggleStatus={this.handleToggleStatus}
              />
            ))}

        </div>

        <FilterSheet
          isOpen={isFilterOpen}
          onClose={this.closeFilter}
          onApply={this.applyFilter}
          province={filterProvince}
          city={filterCity}
          specialty={filterSpecialty}
          onProvinceChange={(e) =>
            this.setState({
              filterProvince: e.target.value,
            })
          }
          onCityChange={(e) =>
            this.setState({
              filterCity: e.target.value,
            })
          }
          onSpecialtyChange={(e) =>
            this.setState({
              filterSpecialty: e.target.value,
            })
          }
        />
      </div>
    );
  }
}

export default TechniciansPage;
